Templates.Starter:
{{/* @dot github.com/donseba/go-webthings/modules/polls.ListView */}}
{{/* Starting point generated by WebThings: every published poll, each with the box component. */}}
<main id="content">
    <h1>{{.Title}}</h1>

    {{range .Polls}}
        {{pollBox $.Key .ID}}
    {{else}}
        <p>No polls yet.</p>
    {{end}}
</main>

Components.Starter:
{{/* @dot github.com/donseba/go-webthings/modules/polls.Poll */}}
{{/* One poll: the vote form, then the results when they may be shown: {{pollBox "survey" "slug"}}. */}}
<section class="wt-poll" id="{{.Anchor}}" aria-labelledby="{{.Anchor}}-question">
    <h3 class="wt-poll__question" id="{{.Anchor}}-question">{{.Question}}</h3>

    {{with .Result}}
        <p class="wt-notice" role="status">
            {{if eq . "voted"}}{{tl localizer "Thank you for voting."}}
            {{else if eq . "already"}}{{tl localizer "You already voted on this question."}}
            {{else if eq . "closed"}}{{tl localizer "This poll is closed."}}
            {{else if eq . "throttled"}}{{tl localizer "Too many votes. Please try again later."}}
            {{else}}{{tl localizer "Please choose one of the options."}}{{end}}
        </p>
    {{end}}

    {{if .CanVote}}
        {{/* The form returns the visitor to the element with the id {{.Anchor}}. */}}
        {{form_open .Form}}
            {{form_field .Form "poll" nil}}
            {{/* The options as radio buttons, labelled with the question. */}}
            {{form_field .Form "option" nil}}

            <button class="wt-button" type="submit">{{tl localizer "Vote"}}</button>
        {{form_close}}
    {{end}}

    {{if .ShowResults}}
        <ul class="wt-poll__results">
            {{range .Options}}
                <li class="wt-poll__result{{if .Chosen}} wt-poll__result--chosen{{end}}">
                    <span class="wt-poll__label">{{.Label}}{{if .Chosen}} <span class="wt-meta">({{tl localizer "your choice"}})</span>{{end}}</span>
                    <span class="wt-poll__percent">{{.Percent}}%</span>
                    <meter class="wt-poll__bar" min="0" max="100" value="{{.Percent}}" aria-hidden="true">{{.Percent}}%</meter>
                </li>
            {{end}}
        </ul>

        <p class="wt-poll__total wt-meta">{{tl localizer "Votes: %d" .Total}}</p>
    {{end}}

    {{if .Closed}}
        <p class="wt-meta">{{tl localizer "Voting has closed."}}</p>
    {{else if not .ClosesAt.IsZero}}
        <p class="wt-meta">{{tl localizer "Voting closes on %s." (date .ClosesAt)}}</p>
    {{end}}
</section>

Types.Decl:
type Fields struct {
	Options Lines `db:"option_ids"`
	// ClosesAt is when voting ends, in UTC; nil keeps the poll open.
	ClosesAt    *time.Time `db:"closes_at"`
	ShowResults bool       `db:"show_results"`
}

type ListView struct {
	// Title is the title of the page the module is mounted on.
	Title string
	// Key is the instance key, for {{pollBox .Key .ID}}.
	Key   string
	Polls []Poll
}

type Poll struct {
	ID       string
	Slug     string
	Question string
	Options  []Option
	// Total is the number of votes.
	Total int
	// ClosesAt is when voting ends, in the site's timezone; zero when the poll
	// stays open.
	ClosesAt time.Time
	Closed   bool
	// Voted is set when the current visitor voted; Option.Chosen marks their choice.
	Voted bool
	// CanVote is set when the poll is open and the visitor has not voted.
	CanVote bool
	// ShowResults is set when results may be shown: after voting, when the
	// poll is closed, or always when editors chose so.
	ShowResults bool
	// Action is the address the vote form posts to.
	Action string
	// Anchor is the id of the element the vote form returns the visitor
	// to, <key>-<ID>, for the element around the form and its result.
	Anchor string
	// Form is the vote form's model (VoteInput, with the poll's ID) for
	// go-form's template functions, such as {{form_open .Form}}; the ids
	// of its fields start with Anchor.
	Form form.RenderModel
	// Result is the outcome of the visitor's last vote on this poll:
	// "voted", "already", "closed", "invalid", "throttled" or empty.
	Result string
}

type ResultRow struct {
	Question string
	EditURL  string
	// Status is "Draft", "Open" or "Closed".
	Status  string
	Options []Option
	Total   int
	// Reset removes the votes; nil without the Delete permission.
	Reset *form.RenderModel
}

type ResultsView struct {
	Title   string
	BackURL string
	Polls   []ResultRow
}

type Service struct {
	// contains unexported fields
}

type Text struct {
	Question string `db:"question"`
	Slug     string `db:"slug"`
	Options  Lines  `db:"option_labels"`
}

type VoteInput struct {
	Poll   string `form:"input,hidden" name:"poll"   maxLength:"64" line:"true"`
	Option string `form:"radios"       name:"option"                            required:"true"`
}
